import type { Metadata } from "next";
import { SITE_URL, clinic } from "@/content/site";

export function absoluteUrl(path = "/") {
  return new URL(path, SITE_URL).toString();
}

export const OG_FALLBACK_IMAGE = "/images/the-dental-suite-and-co-peshawar.jpg";

/** Generated by src/app/opengraph-image.tsx. Routes with their own opengraph-image file override it. */
const DEFAULT_SHARE_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "The Dental Suite & Co. — cosmetic & family dentist at Liberty Mall, University Road, Peshawar",
};

const TITLE_SUFFIX = ` | ${clinic.brand}`;
// Beyond ~65 characters Google truncates the title, so long titles drop the brand suffix.
const MAX_TITLE = 65;

type PageMeta = {
  title: string;
  description: string;
  path: string;
  /** Use the title as-is instead of applying the "| The Dental Suite & Co." template. */
  absoluteTitle?: boolean;
  type?: "website" | "article" | "profile";
  publishedTime?: string;
  /** The route has its own opengraph-image file; config images would override it, so omit them. */
  ownShareImage?: boolean;
};

export function pageMetadata({
  title,
  description,
  path,
  absoluteTitle,
  type = "website",
  publishedTime,
  ownShareImage,
}: PageMeta): Metadata {
  const absolute = absoluteTitle || title.length + TITLE_SUFFIX.length > MAX_TITLE;
  const fullTitle = absolute ? title : `${title}${TITLE_SUFFIX}`;
  return {
    title: absolute ? { absolute: title } : title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type,
      url: path,
      title: fullTitle,
      description,
      siteName: clinic.brand,
      locale: "en_PK",
      ...(ownShareImage ? {} : { images: [DEFAULT_SHARE_IMAGE] }),
      ...(publishedTime ? { publishedTime } : {}),
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      ...(ownShareImage ? {} : { images: [DEFAULT_SHARE_IMAGE.url] }),
    },
  };
}
